DB=os.path.abspath('scratchpad/session_2026-11-06-pipeline-batch-2/walk.db')
ENV={**os.environ,'GUIDEBOOK_DB_PATH':DB}
def db(*a,show=True):
    o=subprocess.run(['python3','scripts/db.py',*a],env=ENV,capture_output=True,text=True)
    out=o.stdout+o.stderr
    bad='REFUS' in out or o.returncode!=0
    print(('FAIL ' if bad else 'ok   ')+a[0], ' | '.join(l.strip() for l in out.splitlines() if 'REFUS' in l or 'extraction_id"' in l or 'scan_id"' in l or 'changed' in l)[:200])
    if bad: print(out[-700:]); sys.exit(1)
